	/** @param array<string,mixed> $payload @param array<string,mixed> $metadata */private function __construct(private readonly string $id,private readonly int $sequence,private readonly string $type,private readonly string $aggregateType,private readonly string $aggregateId,private readonly string $tenantId,private readonly string $actorId,private readonly string $commandFingerprint,private readonly ?string $correlationId,private readonly ?string $causationId,private readonly array $payload,private readonly array $metadata,private readonly string $occurredAt,private readonly string $previousHash,private readonly string $keyId,private readonly string $signature){PanelOperationsGuard::identifier($id,'fabric event id');if($sequence<1){throw new \InvalidArgumentException('Fabric event sequence is invalid.');}PanelOperationsGuard::name($type,'fabric event type',160);PanelOperationsGuard::name($aggregateType,'fabric aggregate type');PanelOperationsGuard::identifier($aggregateId,'fabric aggregate id');PanelOperationsGuard::identifier($tenantId,'fabric event tenant');PanelOperationsGuard::identifier($actorId,'fabric event actor');foreach([$commandFingerprint,$previousHash]as$digest){if(preg_match('/^[a-f0-9]{64}$/D',$digest)!==1){throw new \InvalidArgumentException('Fabric event hash is invalid.');}}foreach([$correlationId,$causationId]as$value){if($value!==null){PanelOperationsGuard::identifier($value,'fabric event relation id');}}PanelOperationsGuard::object($payload,'fabric event payload',4096);PanelOperationsGuard::canonical($payload);PanelOperationsGuard::safeMetadata($metadata,512);PanelOperationsGuard::name($keyId,'fabric event key id');if(preg_match('/^[a-f0-9]{64}$/D',$signature)!==1){throw new \InvalidArgumentException('Fabric event signature is invalid.');}$this->digest=PanelOperationsGuard::digest($this->unsigned());}
