	public function id():string{return$this->id;}public function sequence():int{return$this->sequence;}public function eventType():string{return$this->type;}public function aggregateType():string{return$this->aggregateType;}public function aggregateId():string{return$this->aggregateId;}public function tenantId():string{return$this->tenantId;}public function actorId():string{return$this->actorId;}public function commandFingerprint():string{return$this->commandFingerprint;}public function correlationId():?string{return$this->correlationId;}public function causationId():?string{return$this->causationId;}/** @return array<string,mixed> */public function payload():array{return$this->payload;}/** @return array<string,mixed> */public function metadata():array{return$this->metadata;}public function occurredAt():string{return$this->occurredAt;}public function previousHash():string{return$this->previousHash;}public function keyId():string{return$this->keyId;}public function digest():string{return$this->digest;}public function hash():string{return hash('sha256',$this->digest.$this->signature);}
